import {avatarFor} from './shared.js';

// Presentation only: no game commands, scoring, storage or timing rules are changed.
export function podiumEntries(rows=[]){return rows.filter(p=>p.finishedAt&&Number.isFinite(p.elapsedMs)).slice().sort((a,b)=>a.elapsedMs-b.elapsedMs||(a.finishOrder??a.finishedAt)-(b.finishOrder??b.finishedAt)).slice(0,3).map((p,i)=>({...p,place:i+1}));}
export function ceremonyReady(s){return s.room.status==='ended'||(s.leaderboard.length>0&&s.leaderboard.every(p=>p.finishedAt));}
export function presentationEvents(previous,s){if(!previous)return [];const out=[];if(!previous.room.expired&&s.room.expired)out.push('timeout');if(s.player?.finishedAt&&!previous.player?.finishedAt)out.push('finish');else if(s.player){const before=new Set(previous.player?.completedStages||Array.from({length:previous.player?.stage||0},(_,i)=>i));const after=s.player.completedStages||Array.from({length:s.player.stage||0},(_,i)=>i);if(after.some(i=>!before.has(i))||(previous.player?.stage===s.player.stage&&!previous.player?.serviceReady&&s.player.serviceReady))out.push('server');}return out;}
export function audioPriority(name){return ['gold','silver','bronze','drumroll','finish','server','go','timeout'].includes(name)?2:name==='helpy-talk'?0:1;}
export function soundDuration(name){return name==='drumroll'?1900:Math.ceil(Math.max(name==='gold'?2.4:0,...(soundNotes[name]||[]).map(([,start,duration])=>start+duration))*1000)+200;}
export function audioVolume(value){const n=Number(value);return Number.isFinite(n)?Math.max(0,Math.min(100,n))/100:1;}
export function countdownSecond(room,now){if(room.status!=='running'||!room.startedAt)return null;return Math.max(0,Math.ceil((room.startedAt-now)/1000));}
export function endCountdownSound(seconds){return seconds>=1&&seconds<=15?(seconds<=5?'countdown-end':'countdown-warning'):null;}
export const lobbyMelody=[262,330,392,494,440,392,330,294];
export const soundNotes={
 'helpy-talk':[[290,0,.07,'triangle'],[390,.085,.06,'triangle'],[320,.16,.1,'triangle']],
 'countdown-warning':[[660,0,.12,'sine']],
 'countdown-end':[[880,0,.16,'sine']],
 countdown:[[740,0,.14,'sine']],
 go:[[523,0,.14],[784,.14,.14],[1047,.28,.5]],
 'command-error':[[180,0,.10,'square'],[105,.10,.16,'square']],
 'answer-error':[[95,0,.22,'sawtooth'],[72,.16,.26,'sawtooth']],
 server:[[523,0,.12],[659,.12,.12],[784,.24,.26]],
 finish:[[523,0,.16],[659,.16,.16],[784,.32,.16],[1047,.5,.6]],
 timeout:[[330,0,.3],[277,.35,.3],[220,.7,.7]],
 bronze:[[392,0,.18],[494,.2,.18],[587,.4,.5]],
 silver:[[440,0,.15],[554,.15,.15],[659,.3,.2],[880,.55,.5]],
 gold:[[523,0,.2],[659,.12,.2],[784,.24,.2],[1047,.5,.7],[1319,.6,.7],[1568,.75,1.1]]
};

if(typeof document!=='undefined')installPresentation();
function installPresentation(){
 const cache=new Map(),pending=[],nodes=new Set();let context=null,master=null,volume=1,musicTimer=null,liveState=null,liveSynced=0,lastCountdown=null,lastEndCountdown=null,lastTalk=0;const musicNodes=new Set(),speechNodes=new Set();let speechBlockedUntil=0;const lastSuccess=new Map();let enabled=true,lastCommandError=0,lastSound=0,activeRoom=null,revealTimers=[],queuedCeremonies=[];
 try{enabled=localStorage.getItem('arenaSound')!=='off';const saved=localStorage.getItem('arenaVolume');if(saved!==null)volume=audioVolume(saved);}catch{}
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const time=ms=>{const sec=Math.floor(ms/1000);return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')+'.'+Math.floor(ms%1000/100);};
 const toggle=document.createElement('button');toggle.id='sound-toggle';toggle.type='button';toggle.className='sound-toggle';const controls=document.createElement('div');controls.className='audio-controls';controls.append(toggle);const slider=document.createElement('input');slider.type='range';slider.min='0';slider.max='100';slider.step='1';slider.value=String(Math.round(volume*100));slider.id='audio-volume';slider.setAttribute('aria-label','Volume du jeu');slider.title='Volume du jeu';controls.append(slider);const volumeLabel=document.createElement('output');volumeLabel.id='audio-volume-value';volumeLabel.textContent=slider.value+'%';controls.append(volumeLabel);document.querySelector('header')?.append(controls);slider.oninput=()=>{volume=audioVolume(slider.value);volumeLabel.textContent=Math.round(volume*100)+'%';try{localStorage.setItem('arenaVolume',slider.value);}catch{}if(master)master.gain.setTargetAtTime(volume*9,context.currentTime,.03);};
 function updateToggle(){toggle.textContent=enabled?'♫ Son':'♫ Muet';toggle.setAttribute('aria-pressed',String(enabled));toggle.setAttribute('aria-label',enabled?'Couper les effets sonores':'Activer les effets sonores');}updateToggle();
 async function unlock(){if(!enabled)return;try{const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)return;if(!context){context=new C();master=context.createGain();master.gain.value=volume*9;const compressor=context.createDynamicsCompressor();compressor.threshold.value=-4;compressor.knee.value=8;compressor.ratio.value=8;compressor.attack.value=.003;compressor.release.value=.15;const limiter=context.createWaveShaper();const curve=new Float32Array(4096);for(let i=0;i<curve.length;i++){const x=(i/(curve.length-1))*2-1;curve[i]=.96*Math.tanh(x*1.2);}limiter.curve=curve;limiter.oversample='4x';master.connect(compressor);compressor.connect(limiter);limiter.connect(context.destination);}if(context.state==='suspended')await context.resume();if(context.state==='running'&&pending.length){const sound=pending.pop();pending.length=0;play(sound);}syncMusic();}catch{}}
 document.addEventListener('pointerdown',unlock,{passive:true});document.addEventListener('keydown',unlock);
 function stopMusic(){if(musicTimer!==null)clearInterval(musicTimer);musicTimer=null;for(const node of musicNodes){try{node.stop();}catch{}}musicNodes.clear();}
 function stopSpeech(){for(const node of speechNodes){try{node.stop();}catch{}}speechNodes.clear();}
 function stopSounds(){stopMusic();stopSpeech();speechBlockedUntil=0;for(const node of nodes){try{node.stop();}catch{}}nodes.clear();pending.length=0;}
 toggle.onclick=()=>{enabled=!enabled;try{localStorage.setItem('arenaSound',enabled?'on':'off');}catch{}updateToggle();if(enabled)unlock();else stopSounds();};
 function tone(frequency,offset,duration,type='sine',level=.07,endFrequency,channel='fx'){if(!context||!enabled)return;const start=context.currentTime+offset,osc=context.createOscillator(),gain=context.createGain();osc.type=type;osc.frequency.setValueAtTime(frequency,start);if(endFrequency)osc.frequency.exponentialRampToValueAtTime(endFrequency,start+duration);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(level,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain);gain.connect(master);nodes.add(osc);if(channel==='music')musicNodes.add(osc);if(channel==='speech')speechNodes.add(osc);osc.onended=()=>{nodes.delete(osc);musicNodes.delete(osc);speechNodes.delete(osc);osc.disconnect();gain.disconnect();};osc.start(start);osc.stop(start+duration+.03);}
 function play(name){if(!enabled)return;const now=Date.now();if(context?.state==='running'&&!document.hidden&&['server','finish'].includes(name)){if(now-(lastSuccess.get(name)||0)<150)return;lastSuccess.set(name,now);}if(audioPriority(name)>=2){stopSpeech();speechBlockedUntil=Math.max(speechBlockedUntil,now+soundDuration(name));}if(name==='helpy-talk'&&now<speechBlockedUntil)return;
  if(!context||context.state!=='running'){if(!pending.length||audioPriority(name)>=audioPriority(pending.at(-1)))pending.splice(0,pending.length,name);return;}if(document.hidden)return;
  if(name==='helpy-talk'){if(now-lastTalk<900)return;lastTalk=now;}if(name==='answer-error'&&now-lastCommandError<250)return;if(name==='command-error')lastCommandError=now;if(['command-error','answer-error'].includes(name)&&now-lastSound<130)return;lastSound=now;
  if(name==='drumroll'){for(let i=0;i<18;i++)tone(90+(i%3)*18,i*.09,.09,'triangle',.025+i*.001,45);tone(130,.1,1.6,'sine',.06,330);return;}
  const notes=soundNotes[name]||[];notes.forEach(([f,o,d,t])=>tone(f,o,d,t||'sine',name==='answer-error'?.045:.065,name==='answer-error'?f*.65:undefined,name==='helpy-talk'?'speech':'fx'));
  if(name==='gold'){[262,330,392].forEach(f=>tone(f,.5,1.9,'triangle',.025));}
 }
 function lobbyPhrase(){if(!context||!enabled||document.hidden)return;for(let i=0;i<lobbyMelody.length;i++)tone(lobbyMelody[i],i*.5,.32,'triangle',.018,undefined,'music');for(let i=0;i<4;i++)tone([131,165,147,196][i],i, .7,'sine',.025,undefined,'music');}
 function syncMusic(){const lobby=liveState?liveState.room.status==='waiting':location.pathname==='/';const shouldPlay=enabled&&context?.state==='running'&&!document.hidden&&!activeRoom&&lobby;if(!shouldPlay){stopMusic();return;}if(musicTimer===null){lobbyPhrase();musicTimer=setInterval(lobbyPhrase,4000);}}
 function updateCountdown(){if(!liveState||document.hidden)return;const now=(liveState.serverNow||liveSynced)+(Date.now()-liveSynced),second=countdownSecond(liveState.room,now);if(second===null){lastCountdown=null;lastEndCountdown=null;return;}if(liveState.room.timeLimitMs&&now>=liveState.room.startedAt&&!ceremonyReady(liveState)){const elapsed=liveState.room.elapsedMs+Math.max(0,now-(liveState.serverNow||now));const remaining=Math.ceil((liveState.room.timeLimitMs-elapsed)/1000),endKey=liveState.room.code+':end:'+remaining;const warning=endCountdownSound(remaining);if(warning&&lastEndCountdown!==endKey){lastEndCountdown=endKey;play(warning);}}const key=liveState.room.code+':'+second;if(lastCountdown===key)return;const wasCounting=lastCountdown?.startsWith(liveState.room.code+':');lastCountdown=key;if(second>0&&second<=5)play('countdown');else if(second===0&&wasCounting&&now-liveState.room.startedAt<1500)play('go');}
 setInterval(updateCountdown,100);
 const dialog=document.createElement('dialog');dialog.id='podium-ceremony';dialog.setAttribute('aria-label','Podium final');document.body.append(dialog);
 function seen(code){try{return sessionStorage.getItem('arenaPodium:'+code)==='seen';}catch{return false;}}
 function markSeen(code){try{sessionStorage.setItem('arenaPodium:'+code,'seen');}catch{}}
 function schedule(fn,ms){revealTimers.push(setTimeout(()=>{if(activeRoom)fn();},ms));}
 function closeCeremony(){for(const t of revealTimers)clearTimeout(t);revealTimers=[];stopSounds();activeRoom=null;syncMusic();if(dialog.open)dialog.close();dialog.innerHTML='';dialog.className='';if(queuedCeremonies.length){const next=queuedCeremonies.shift();scheduleOpen(next);}}
 function scheduleOpen(s){setTimeout(()=>openCeremony(s),400);}
 function openCeremony(s){if(!ceremonyReady(s))return;if(activeRoom){if(activeRoom!==s.room.code&&!queuedCeremonies.some(r=>r.room.code===s.room.code))queuedCeremonies.push(s);return;}activeRoom=s.room.code;stopMusic();markSeen(activeRoom);const winners=podiumEntries(s.leaderboard),own=s.player?.labId||s.player?.id;
  dialog.innerHTML=`<button type="button" class="podium-close" aria-label="Fermer le podium">✕</button><div class="podium-rays" aria-hidden="true"></div><div class="podium-confetti" aria-hidden="true">${Array.from({length:48},(_,i)=>`<i data-spark="${i}"></i>`).join('')}</div><div class="podium-intro"><p>HYPERVISOR ARENA · ${esc(s.room.title||s.room.code)}</p><h1>LE CLASSEMENT FINAL</h1><span id="podium-announcer" role="status" aria-live="polite">${winners.length?'Les opérateurs ont parlé. Place au podium…':'Aucun participant n’a terminé le contrôle final.'}</span></div><div class="podium-stage">${[2,1,3].map(place=>{const p=winners.find(p=>p.place===place);return `<article class="podium-place place-${place}" data-place="${place}" ${p?'':'hidden'} aria-hidden="true">${p?`<div class="podium-winner ${p.id===own?'your-podium':''}"><span class="podium-medal">${['🥇','🥈','🥉'][place-1]}</span><span class="podium-avatar">${avatarFor(p.avatar).emoji}</span><h2>${esc(p.name)}</h2>${p.id===own?'<b class="podium-you">C’EST TON '+(p.members?'ÉQUIPE':'RÉSULTAT')+' !</b>':''}<p>${time(p.elapsedMs)}</p>${p.members?'<small>'+p.members.map(m=>esc(m.name)).join(' · ')+'</small>':''}</div><div class="podium-block"><strong>${place}</strong></div>`:''}</article>`;}).join('')}</div><p class="podium-note">${winners.length?'Classement des participants ayant réussi le contrôle final · temps serveur.':'Les résultats incomplets restent consultables dans le classement.'}</p><button type="button" class="secondary podium-return">Revenir au classement</button>`;
  dialog.querySelectorAll('[data-spark]').forEach(el=>{const i=Number(el.dataset.spark);el.style.setProperty('--x',((i*37)%100)+'%');el.style.setProperty('--delay',((i%12)*.14)+'s');el.style.setProperty('--turn',(i*31)+'deg');});
  dialog.querySelector('.podium-close').onclick=closeCeremony;dialog.querySelector('.podium-return').onclick=closeCeremony;dialog.oncancel=e=>{e.preventDefault();closeCeremony();};if(!dialog.open)dialog.showModal();
  if(!winners.length)return;if(winners.length>1)play('drumroll');let at=1600;const order=[3,2,1].filter(place=>winners.some(p=>p.place===place));for(const place of order){if(place===1)schedule(()=>{dialog.classList.add('gold-build');dialog.querySelector('#podium-announcer').textContent='Et à la première place…';play('drumroll');},Math.max(0,at-1500));schedule(()=>{const card=dialog.querySelector('[data-place="'+place+'"]'),p=winners.find(p=>p.place===place);card.classList.add('revealed');card.setAttribute('aria-hidden','false');dialog.querySelector('#podium-announcer').textContent=(place===1?'VICTOIRE — ':place===2?'DEUXIÈME PLACE — ':'TROISIÈME PLACE — ')+p.name;play(place===1?'gold':place===2?'silver':'bronze');if(place===1){dialog.classList.add('champion-revealed');dialog.classList.remove('gold-build');}},at);at+=place===2?4200:3200;}
 }
 document.addEventListener('arena:feedback',e=>play(e.detail.type));
 document.addEventListener('arena:state',e=>{const {state:s,scope}=e.detail,previous=cache.get(s.room.code);if(scope!=='admin'){liveState=s;liveSynced=Date.now();syncMusic();updateCountdown();}cache.set(s.room.code,s);for(const effect of presentationEvents(previous,s))play(effect);
  if(ceremonyReady(s)){const bar=scope==='admin'?null:document.querySelector('.room-bar');if(bar&&!bar.querySelector('[data-podium-room]')){const replay=document.createElement('button');replay.type='button';replay.className='text-button podium-replay';replay.dataset.podiumRoom=s.room.code;replay.textContent='🏆 Voir le podium';bar.append(replay);}if(!seen(s.room.code)&&(scope!=='admin'||previous&&!ceremonyReady(previous)))scheduleOpen(s);}
 });
 document.addEventListener('click',e=>{const button=e.target.closest('[data-podium-room]');if(button){const s=cache.get(button.dataset.podiumRoom);if(s)openCeremony(s);}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSounds();else{syncMusic();updateCountdown();}});
}
